<?php require_once '../functions.php'; require_admin(); if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$status=$_POST['status']??'';$allowed=['pending','paid','processing','shipped','completed','cancelled'];if(in_array($status,$allowed,true)){$s=$koneksi->prepare('UPDATE pesanan SET status=? WHERE id_pesanan=?');$s->bind_param('si',$status,$id);$s->execute();flash('success','Status pesanan diperbarui.');}redirect('pesanan.php');}$title='Kelola Pesanan';$list=$koneksi->query('SELECT p.*,u.nama,pay.status pay_status,pay.reference FROM pesanan p JOIN users u ON u.id_user=p.id_user LEFT JOIN pembayaran pay ON pay.id_pesanan=p.id_pesanan ORDER BY p.id_pesanan DESC');include 'header.php'; ?>
<div class="container"><div class="section-head"><div><h1>Kelola Pesanan</h1><p class="muted">Perbarui status pesanan setelah pembayaran.</p></div></div><div class="table-wrap"><table><tr><th>ID</th><th>Pelanggan</th><th>Total</th><th>Pembayaran</th><th>Status</th><th>Update</th></tr><?php while($o=$list->fetch_assoc()):?><tr><td><b>#<?=$o['id_pesanan']?></b><br><small><?=e($o['created_at'])?></small></td><td><?=e($o['nama'])?></td><td><?=rupiah($o['total'])?></td><td><?=e(payment_status_label($o['pay_status']??'pending'))?><br><small><?=e($o['reference']??'-')?></small></td><td><?=e(order_status_label($o['status']))?></td><td><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$o['id_pesanan']?>"><select name="status"><option value="pending">Menunggu Pembayaran</option><option value="paid">Sudah Dibayar</option><option value="processing">Diproses</option><option value="shipped">Dikirim</option><option value="completed">Selesai</option><option value="cancelled">Dibatalkan</option></select><button class="btn small">Update</button></form></td></tr><?php endwhile;?></table></div></div><?php include '../footer.php'; ?>
